insert into step (milestone_id, position, title, est_minutes, outcome) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask') and m.position = 3), 3, 'Recover after a crash', 45, 'After you cut the active file in the middle of its last record, the store starts, serves every earlier value, and reports the dropped record.');
