insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-bitcask') and m.position = 3) and s.position = 3), 'hint', '', 'Simulate the crash by truncating a copy of the file.', 'generated');
