insert into step (milestone_id, position, title, est_minutes, outcome) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-curl') and m.position = 3), 2, 'Send a body', 45, 'A POST to http://eu.httpbin.org/post with a small JSON body and a JSON Content-Type echoes the body back under json and a Content-Length equal to its size in bytes, and a PUT to http://eu.httpbin.org/put does the same.');
