insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 1) and s.position = 1), 'build', 'build', 'Encode a host name as labels, each preceded by its length and ended by a zero byte. Build the 12-byte header with the ID 22, recursion desired set, a question count of 1 and zero for the other counts, every number written as two bytes, high byte first.');
