insert into step (milestone_id, position, title, est_minutes, outcome) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3), 2, 'Follow the referrals', 60, 'Resolving dns.google.com from the root prints each server queried and ends with the same address as dig, and a name whose servers have no glue is still resolved, with the total number of queries capped.');
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-dns-resolver') and m.position = 3) and s.position = 2), 'build', 'build', 'Loop: send the query to the current server; stop when the answer section holds an A record; otherwise take a name server from the authority section and its address from the additional section, and ask it. When a name server has no address, resolve its name from the root first. Stop after a fixed number of queries.');
