insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1) and s.position = 2), 'build', 'build', 'Skip symbolic links, and report then skip any folder or file the tool cannot read, so one bad entry never stops the scan.');
