insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1) and s.position = 2), 'hint', '', 'Create the loop on purpose and watch what your walker does.', 'generated');
insert into step (milestone_id, position, title, est_minutes, outcome) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 1), 3, 'Group by size', 30, 'On the test data every file appears in one size group, because they are all 100 bytes, and a file of a unique size appears in none.');
