insert into step_concept (step_id, concept_id) select (select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 3) and s.position = 2), id from concept where slug in ('cache-invalidation');
