insert into step (milestone_id, position, title, est_minutes, outcome) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-duplicate-files') and m.position = 3), 3, 'Delete with care', 45, 'Pressing Enter, typing a letter or ending the input keeps every file; typing a listed number deletes exactly that file and prints which one was removed.');
