insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-grep') and m.position = 1) and s.position = 1), 'build', 'build', 'Make your grep take a pattern and a file and print every line that contains it, reading one line at a time. On the easy route, use your language''s regex library; on the hard route, start an engine that matches plain letters.');
