insert into step (milestone_id, position, title, est_minutes, outcome) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1), 2, 'Build the tree', 60, 'Your tree for the worked example in the OpenDSA tutorial has the same total weight at the root and the same code lengths, and an empty file and a one-symbol file are handled without a crash.');
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-huffman') and m.position = 1) and s.position = 2), 'build', 'build', 'Build the Huffman tree from the counts with a priority queue that always hands back the lightest node, joining the two lightest until one remains. Pick and write down a tie-breaking rule.');
