insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-rate-limiter') and m.position = 1) and s.position = 2), 'hint', '', 'You can refill with a timer, or work out the tokens earned from the time since the last request. Which needs less work per client?', 'generated');
