insert into step_concept (step_id, concept_id) select (select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 1), id from concept where slug in ('http-redirects', 'rest-api-design');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 1), 'hint', '', 'Check the Location header carries the full long URL, exactly as stored.', 'generated');
insert into step (milestone_id, position, title, est_minutes, outcome) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3), 2, 'Why 302 and not 301', 30, 'Three browser visits with 302 appear as three log entries, and your notes record that later visits to the 301 key no longer reached the service.');
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 2), 'build', 'build', 'Log every redirect your service sends. Visit the same short URL three times in a browser, then try one key with 301 and see what the browser does on later visits.');
insert into step_concept (step_id, concept_id) select (select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 2), id from concept where slug in ('http-redirects');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 2), 'hint', '', 'Use a fresh browser profile or clear its cache after the 301 test.', 'generated');
insert into step (milestone_id, position, title, est_minutes, outcome) values ((select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3), 3, 'Delete a short URL', 45, 'After DELETE, a GET for the key gives 404, also after a restart, and a second DELETE of the same key changes nothing and answers the way your notes say it should.');
insert into task (step_id, role, kind, prompt) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 3), 'build', 'build', 'Accept DELETE for a key: remove the key and its long URL from the store and answer 200 OK. Decide what a DELETE for a key that does not exist answers, and test deleting the same key twice.');
insert into step_concept (step_id, concept_id) select (select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 3), id from concept where slug in ('idempotency', 'rest-api-design', 'key-value-store');
insert into hint (step_id, level, language, body, content_status) values ((select s.id from step s where s.milestone_id = (select m.id from milestone m where m.challenge_id = (select id from challenge where source = 'coding_challenges' and slug = 'challenge-url-shortener') and m.position = 3) and s.position = 3), 'hint', '', 'The state after one delete and after two must be the same. Is the reply allowed to differ?', 'generated');
insert into challenge (source, slug, title, source_url) values ('coding_challenges', 'challenge-wc', 'Build your own wc', 'https://codingchallenges.fyi/challenges/challenge-wc') on conflict (source, slug) do nothing;
insert into project_concept (challenge_id, concept_id, position, where_text, explain_prompt, explain_rubric) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), (select id from concept where slug = 'text-encoding-utf8'), 1, '-c counts bytes and -m counts characters. On any file that is not plain English the two differ, because UTF-8 stores a character in 1 to 4 bytes.', 'A sign-up form allows names of up to 20 characters, but the database column holds 20 bytes. A user types a 20-character name with several accented letters and it fails to save. Explain what happened, in terms of how UTF-8 stores the name.', '[{"id":"e1","point":"Text is stored as code points, and UTF-8 writes each code point as 1 to 4 bytes"},{"id":"e2","point":"Plain English letters take 1 byte, but accented letters such as é or ó take 2, so 20 characters can need more than 20 bytes"},{"id":"e3","point":"The limit has to be counted in one unit on both sides: either count characters everywhere, or give the column room for the encoded bytes"}]'::jsonb);
insert into project_concept (challenge_id, concept_id, position, where_text, explain_prompt, explain_rubric) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), (select id from concept where slug = 'utf16-code-units'), 2, '-m has to count code points. Many languages store strings as UTF-16, where a string length counts 16-bit units, not characters, so a naive count is wrong for emoji.', 'A chat app limits messages to 100 characters using the string length of a language that stores strings in UTF-16. Users say emoji-heavy messages are cut off early, and some end with a broken symbol. Explain both problems.', '[{"id":"e1","point":"UTF-16 stores code points above U+FFFF, which includes most emoji, as a surrogate pair of two 16-bit units"},{"id":"e2","point":"The string length counts units, so each such emoji counts as 2 and the limit is reached early"},{"id":"e3","point":"Cutting at a unit boundary can split a surrogate pair, leaving half an emoji that shows as a broken symbol"}]'::jsonb);
insert into project_concept (challenge_id, concept_id, position, where_text, explain_prompt, explain_rubric) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), (select id from concept where slug = 'grapheme-clusters'), 3, 'wc -m counts code points, which is not always what a person sees as one character. A thumbs-up with a skin tone is one visible symbol made of two code points.', '👍🏽 looks like one character. Explain what it is made of, what a code-point count such as wc -m reports for it, and why a text editor still moves the cursor over it in one step.', '[{"id":"e1","point":"It is two code points: the thumbs-up emoji followed by a skin-tone modifier"},{"id":"e2","point":"A code-point count reports 2"},{"id":"e3","point":"Editors move by grapheme clusters, the units a person reads as one character, so the cursor treats both code points as one"},{"id":"e4","point":"Both counts are correct for different purposes, so a tool must say which one it reports"}]'::jsonb);
insert into project_concept (challenge_id, concept_id, position, where_text, explain_prompt, explain_rubric) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), (select id from concept where slug = 'explicit-charsets'), 4, 'To count characters and words your tool decodes bytes into characters, and it must name the encoding instead of relying on the machine or locale default.', 'Your tool gives the right -m count on your laptop but a different one on a colleague''s machine for the same file. Explain a likely cause and how to make the result the same everywhere.', '[{"id":"e1","point":"Decoding bytes into characters needs an encoding, and if none is named the platform or locale default is used, which differs between machines"},{"id":"e2","point":"Name the encoding explicitly, for example UTF-8, or let the user choose it with an option"},{"id":"e3","point":"The byte count does not change, because counting bytes needs no decoding"}]'::jsonb);
insert into project_concept (challenge_id, concept_id, position, where_text, explain_prompt, explain_rubric) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), (select id from concept where slug = 'decoding-across-chunks'), 5, 'You read input in chunks, and a chunk can end in the middle of a multi-byte character. -m and -w must not break that character.', 'A service reads a UTF-8 file 4,096 bytes at a time and decodes each chunk on its own. Some characters come out as replacement symbols, and only in large files. Explain why, and what the decoder needs to do instead.', '[{"id":"e1","point":"A UTF-8 character can be up to 4 bytes, so a chunk boundary can fall inside one"},{"id":"e2","point":"Decoding each chunk alone sees an incomplete sequence at the edge and replaces it"},{"id":"e3","point":"One decoder should be kept for the whole input, holding the leftover bytes until the next chunk completes the character, and flushing at the end"}]'::jsonb);
insert into project_concept (challenge_id, concept_id, position, where_text, explain_prompt, explain_rubric) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), (select id from concept where slug = 'malformed-input'), 6, 'Real files contain bytes that are not valid UTF-8. Your tool has to pick a policy for them and match the reference tool.', 'A log file contains a few bytes that are not valid UTF-8. Describe the ways a decoder can treat them, and how each choice changes a character count.', '[{"id":"e1","point":"Stop with an error, so there is no count"},{"id":"e2","point":"Replace each bad sequence with the replacement character U+FFFD, which is then counted as a character"},{"id":"e3","point":"Skip the bad bytes, so they are not counted as characters"},{"id":"e4","point":"Pick one policy on purpose, match the reference tool, and say which one you chose"}]'::jsonb);
insert into project_concept (challenge_id, concept_id, position, where_text, explain_prompt, explain_rubric) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), (select id from concept where slug = 'streaming-constant-memory'), 7, 'wc must handle files bigger than memory and pipes that never say how long they are. Your tool keeps only one buffer and a few counters.', 'Your tool counts a 20 GB log on a machine with 8 GB of memory. Explain how much memory it needs and why, and what would happen if it read the whole file first.', '[{"id":"e1","point":"It reads a fixed-size buffer at a time and reuses that buffer for every read"},{"id":"e2","point":"Between reads it keeps only the counters and a little state, so memory does not grow with the size of the input"},{"id":"e3","point":"Reading the whole file first needs memory in proportion to the file, so it fails or slows to a crawl, and it cannot work on an endless pipe"}]'::jsonb);
insert into project_concept (challenge_id, concept_id, position, where_text, explain_prompt, explain_rubric) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), (select id from concept where slug = 'stream-read-contract'), 8, 'Your read loop must use the number of bytes each read actually returned, not the size of the buffer.', 'A read asks for 8,192 bytes and gets back 3. Explain what that means, what the program should do next, and how it knows the input has ended.', '[{"id":"e1","point":"A read may return fewer bytes than asked for, for example near the end or from a pipe, and that is not an error"},{"id":"e2","point":"Only the bytes it reported are valid; the rest of the buffer still holds old data and must be ignored"},{"id":"e3","point":"The program keeps reading until a read reports the end of the input"}]'::jsonb);
insert into project_concept (challenge_id, concept_id, position, where_text, explain_prompt, explain_rubric) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), (select id from concept where slug = 'word-state-machine'), 9, '-w counts words across chunk boundaries, and -l counts newline characters, so a final line without a newline is not counted.', 'Explain how a program can count words in a stream it only sees in pieces, so that a word split across two pieces is counted once. Then explain why a file whose last line has no newline reports one line fewer.', '[{"id":"e1","point":"There are two states, inside a word and between words"},{"id":"e2","point":"A word is counted on the change from whitespace to a non-whitespace character"},{"id":"e3","point":"The current state is kept from one piece to the next, so a split word is not counted twice"},{"id":"e4","point":"Lines are counted by newline characters, so a last line without one is not counted"}]'::jsonb);
insert into project_concept (challenge_id, concept_id, position, where_text, explain_prompt, explain_rubric) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), (select id from concept where slug = 'stdin-vs-file'), 10, 'With no file name, ccwc reads standard input. One counting path should serve both a file and a pipe.', 'Explain how one counting routine can work for both a named file and text piped in from another program, and why asking the file system for the size cannot work for piped input.', '[{"id":"e1","point":"Both are a stream of bytes read until the end, so the counting routine only needs something to read from"},{"id":"e2","point":"Which source to use is decided once, where the input is opened"},{"id":"e3","point":"A pipe has no size and can be read only once, so the counts have to be made while reading"}]'::jsonb);
insert into project_concept (challenge_id, concept_id, position, where_text, explain_prompt, explain_rubric) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), (select id from concept where slug = 'cli-subcommands'), 11, 'ccwc takes options, prints results to standard output and errors to standard error, and reports failure through its exit status.', 'ccwc is given three files and the second does not exist. Explain what should go to standard output, what to standard error, what exit status it should return, and why scripts care.', '[{"id":"e1","point":"The counts for the files that exist, and the total, go to standard output"},{"id":"e2","point":"A message naming the missing file goes to standard error"},{"id":"e3","point":"The exit status is non-zero to signal that something failed"},{"id":"e4","point":"Scripts read standard output and check the exit status, so mixing errors into the output, or exiting with 0, breaks them"}]'::jsonb);
insert into project_concept (challenge_id, concept_id, position, where_text, explain_prompt, explain_rubric) values ((select id from challenge where source = 'coding_challenges' and slug = 'challenge-wc'), (select id from concept where slug = 'differential-testing'), 12, 'You check ccwc by running it and the reference wc on the same inputs and comparing the results.', 'All your own tests pass, yet your word count differs from the real wc on a file with unusual spaces. Explain what comparing against a reference tool catches that your own expected values miss, and what must be the same on both sides.', '[{"id":"e1","point":"The reference tool supplies the right answer for any input, including inputs you did not think of"},{"id":"e2","point":"Your own expected values carry your own misunderstanding, so they can agree with a wrong program"},{"id":"e3","point":"Both runs must see the same bytes and the same settings, such as the locale or encoding"}]'::jsonb);
